  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/11/10/le-rallye-de-soulagement-teste-le-biais-de-recence-sans-prouver-la-fin-du-risque',
  'behaviour',
  'article',
  'Le rallye de soulagement teste le biais de récence, sans prouver la fin du risque',
  'Un rebond de 2,3 % du S&P 500 et un recul de 5,85 % du Brent offrent la tentation classique d’extrapoler un jour de répit en un changement durable du risque.',
  '<ul>
<li><strong>Lundi a donné la meilleure séance des actions américaines depuis avril,</strong><span> selon AP, alors que la baisse des prix du pétrole apaisait les craintes d’inflation.</span></li>
<li><strong>Le S&amp;P 500 a gagné 2,3&nbsp;%,</strong><span> le Dow 2,2&nbsp;%, le Nasdaq 2,7&nbsp;% et le Russell 2000, indice des petites capitalisations, 3,1&nbsp;%.</span></li>
<li><strong>Le déclencheur a été une réévaluation du risque énergétique et géopolitique,</strong><span> et non la confirmation d’un accord de paix durable.</span></li>
<li><strong>Le biais de récence incite les clients à confondre une seule séance marquante avec une nouvelle tendance.</strong></li>
<li><strong>Les conseillers peuvent faire du rebond une conversation sur des règles de rééquilibrage établies à l’avance.</strong></li>
</ul>',
  '<p>Lundi a donné la meilleure séance des actions américaines depuis avril, selon AP, alors que la baisse des prix du pétrole apaisait les craintes d’inflation. Le S&amp;P 500 a gagné 2,3&nbsp;%, le Dow 2,2&nbsp;%, le Nasdaq 2,7&nbsp;% et le Russell 2000, indice des petites capitalisations, 3,1&nbsp;%. La distinction importante, pour un conseiller, est celle qui sépare l’observation rapportée de l’inférence que les investisseurs sont tentés d’en tirer.</p><h2>Pourquoi le soulagement ressemble à de la certitude</h2><p>Le déclencheur a été une réévaluation du risque énergétique et géopolitique, et non la confirmation d’un accord de paix durable. Le S&amp;P 500 a gagné 2,3&nbsp;%, le Dow 2,2&nbsp;%, le Nasdaq 2,7&nbsp;% et le Russell 2000, indice des petites capitalisations, 3,1&nbsp;%. Cela importe, car une même manchette peut avoir des conséquences différentes pour un investisseur à long terme, un ménage qui finance des dépenses à court terme et un client détenant une position concentrée. La bonne réponse dépend des besoins de flux de trésorerie, de la valorisation et de la capacité à prendre des risques, et non simplement du sens de la dernière donnée publiée.</p><p>Pour les conseillers canadiens, la question pratique est de savoir quelle hypothèse du plan du client a réellement changé. Un changement temporaire de sentiment peut modifier les cours sans modifier les obligations futures. À l’inverse, une proposition réglementaire, une détérioration de l’emploi ou une perturbation persistante de l’approvisionnement peut modifier les flux de trésorerie attendus sur lesquels repose le plan. Cette distinction est au cœur d’un examen rigoureux.</p><h2>La différence entre une nouvelle information et un nouveau récit</h2><p>Le biais de récence incite les clients à confondre une seule séance marquante avec une nouvelle tendance. Le déclencheur a été une réévaluation du risque énergétique et géopolitique, et non la confirmation d’un accord de paix durable. Cela importe, car une même manchette peut avoir des conséquences différentes pour un investisseur à long terme, un ménage qui finance des dépenses à court terme et un client détenant une position concentrée. La bonne réponse dépend des besoins de flux de trésorerie, de la valorisation et de la capacité à prendre des risques, et non simplement du sens de la dernière donnée publiée.</p><p>Pour les conseillers canadiens, la question pratique est de savoir quelle hypothèse du plan du client a réellement changé. Un changement temporaire de sentiment peut modifier les cours sans modifier les obligations futures. À l’inverse, une proposition réglementaire, une détérioration de l’emploi ou une perturbation persistante de l’approvisionnement peut modifier les flux de trésorerie attendus sur lesquels repose le plan. Cette distinction est au cœur d’un examen rigoureux.</p><div class="hdq-chart"><div style="background:#fff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;"><div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;font-size:13px;font-weight:700;">COMPORTEMENT | COMPARAISON VÉRIFIÉE</div><div style="padding:12px 14px 8px;"><script>(function(){var _cs=document.currentScript;var NS="http://www.w3.org/2000/svg";function el(t,a,v){var e=document.createElementNS(NS,t);Object.keys(a).forEach(function(k){e.setAttribute(k,a[k]);});if(v!==undefined)e.textContent=v;return e;}var svg=el("svg",{viewBox:"0 0 680 300",width:"100%",role:"img","aria-label":"comportement, comparaison vérifiée"});var labels=["S&P 500", "Dow", "Nasdaq", "Russell 2000"],values=[2.3, 2.2, 2.7, 3.1],max=3.1;svg.appendChild(el("line",{x1:205,y1:15,x2:205,y2:265,stroke:"#dddddd"}));values.forEach(function(v,i){var y=28+i*(225/values.length);var w=Math.abs(v)/max*375;svg.appendChild(el("text",{x:8,y:y+15,"font-size":12,fill:"#444444"},labels[i]));svg.appendChild(el("rect",{x:205,y:y,width:w,height:25,fill:v<0?"#b65a52":"#526a80",rx:2}));svg.appendChild(el("text",{x:210+w,y:y+17,"font-size":12,fill:"#222222"},v.toLocaleString("fr-CA")));});_cs.parentNode.appendChild(svg);})();</script></div><div style="font-size:10px;color:#888;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Associated Press, clôture des marchés américains, 9 novembre 2026. Les valeurs reflètent les unités de la source telles qu’indiquées. | hdq.ca</div></div></div><p style="font-size:11px;color:#666;">Note sur le graphique&nbsp;: la comparaison porte sur les chiffres publiés&nbsp;; elle ne constitue pas une prévision.</p><h2>Une réponse de conseiller qui ne dépend pas de mardi</h2><p>Les conseillers peuvent faire du rebond une conversation sur des règles de rééquilibrage établies à l’avance. Le biais de récence incite les clients à confondre une seule séance marquante avec une nouvelle tendance. Cela importe, car une même manchette peut avoir des conséquences différentes pour un investisseur à long terme, un ménage qui finance des dépenses à court terme et un client détenant une position concentrée. La bonne réponse dépend des besoins de flux de trésorerie, de la valorisation et de la capacité à prendre des risques, et non simplement du sens de la dernière donnée publiée.</p><p>Pour les conseillers canadiens, la question pratique est de savoir quelle hypothèse du plan du client a réellement changé. Un changement temporaire de sentiment peut modifier les cours sans modifier les obligations futures. À l’inverse, une proposition réglementaire, une détérioration de l’emploi ou une perturbation persistante de l’approvisionnement peut modifier les flux de trésorerie attendus sur lesquels repose le plan. Cette distinction est au cœur d’un examen rigoureux.</p><p>Les conseillers peuvent faire du rebond une conversation sur des règles de rééquilibrage établies à l’avance. Une règle de décision documentée, une analyse de scénarios et un suivi planifié peuvent être plus utiles qu’une prédiction assurée. Les chiffres et l’état des politiques sont présentés à la date limite de recherche de 6&nbsp;h&nbsp;48, heure de Toronto, le 10 novembre 2026.</p>',
  '<div class="toolkit-section"><div class="toolkit-section-label">Ce qu’ils ressentent</div><p>Les clients peuvent être partagés entre le soulagement devant le dernier mouvement et la crainte que l’incertitude sous-jacente n’ait pas disparu. Ceux qui ont récemment modifié leur répartition de l’actif peuvent être particulièrement sensibles à la prochaine manchette.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Quoi dire</div><p>Les derniers chiffres méritent de l’attention, mais ils n’exigent pas, à eux seuls, un changement de portefeuille. Nous pouvons examiner ce qui a changé, ce qui reste incertain et si votre plan actuel est toujours adapté.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Qui est touché</div><p>Les clients qui détiennent des positions concentrées, qui prévoient des retraits, qui ont des besoins de refinancement ou dont l’horizon de placement est court méritent une discussion plus précise.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Liste de vérification</div><ul><li>Examiner la concentration et les besoins de liquidité.</li><li>Comparer les expositions actuelles avec la politique de placement écrite.</li><li>Vérifier les dates et l’état d’avancement législatif avant de mettre en œuvre des changements fiscaux.</li><li>Consigner la justification de tout ajustement recommandé.</li></ul></div><div class="toolkit-section"><div class="toolkit-section-label">Modèle de courriel de suivi</div><div class="email-template" id="respond-email"><strong>Objet&nbsp;: Un éclairage utile sur l’actualité en finance comportementale</strong><br><br>Bonjour [Nom du client],<br><br>Je souhaite vous faire part d’un bref point sur la finance comportementale. Lundi a donné la meilleure séance des actions américaines depuis avril, selon AP, alors que la baisse des prix du pétrole apaisait les craintes d’inflation. C’est un bon moment pour revoir vos objectifs et votre positionnement actuel plutôt que de réagir à une seule séance. Faites-moi savoir si vous souhaitez planifier un bref examen.<br><br>Cordialement,<br>[Votre nom]<br><br><em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em></div><button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button></div>',
  '<div class="toolkit-section"><div class="toolkit-section-label">Profils de clients à cibler</div><p><strong>Clients ayant des expositions concentrées&nbsp;:</strong> ménages dont les décisions sont les plus sensibles aux derniers développements en finance comportementale.</p><p><strong>Investisseurs sur le point de prendre une décision financière&nbsp;:</strong> personnes qui évaluent un changement de portefeuille, un choix de financement ou un événement de liquidité.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Phrase d’accroche</div><p>Les dernières manchettes offrent l’occasion de distinguer la réaction immédiate du marché de ce qui a réellement changé dans les faits sous-jacents.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Proposition de valeur</div><p>Proposer un examen concis, fondé sur des faits, des expositions du client, de ses échéances de décision et de ses scénarios de baisse, sans promettre de résultat sur les marchés.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Questions de découverte</div><ul><li>Qu’est-ce qui vous a amené à reconsidérer votre stratégie actuelle&nbsp;?</li><li>Quel engagement financier à venir est le plus important&nbsp;?</li><li>Quel niveau de volatilité vous obligerait à modifier votre plan&nbsp;?</li></ul></div><div class="toolkit-section"><div class="toolkit-section-label">Modèle de courriel de prospection</div><div class="email-template" id="prospect-email"><strong>Objet&nbsp;: Un éclairage utile sur l’actualité en finance comportementale</strong><br><br>Bonjour [Nom du client],<br><br>J’ai remarqué les derniers développements en finance comportementale. Lundi a donné la meilleure séance des actions américaines depuis avril, selon AP, alors que la baisse des prix du pétrole apaisait les craintes d’inflation. Plutôt que de prendre une décision à partir d’une seule manchette, je serais heureux de vous présenter un court cadre d’analyse pour évaluer ce qui compte pour vos objectifs. Une conversation de 15&nbsp;minutes vous serait-elle utile&nbsp;?<br><br>Cordialement,<br>[Votre nom]<br><br><em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em></div><button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button></div>',
  '[{"value": "2,3 %", "label": "Gain du S&P 500 lundi"}, {"value": "2,7 %", "label": "Gain du Nasdaq lundi"}, {"value": "3,1 %", "label": "Gain du Russell 2000"}, {"value": "5,85 %", "label": "Recul du Brent lundi"}]',
  'behaviour-156.jpg',
  'Image éditoriale provisoire de HDQ.',
  6,
  '2026-11-10T06:54:00',
  'entity:behaviour,theme:november-2026,theme:advisor-planning',
  1,
  'Associated Press, clôture des marchés américains, 9 novembre 2026 ; Reuters, diplomatie iranienne et pétrole, 9 novembre 2026. Source principale : https://apnews.com/article/f7ec9680fc858e3c2505913e7b3a54e2',
  '2026/11/10/the-relief-rally-is-a-test-of-recency-bias-not-proof-the-risk-has-passed'
);

INSERT OR REPLACE INTO articles
