INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/11/10/le-canada-perd-4-700-emplois-le-chomage-atteint-6-7-et-complique-les-perspectives-de-taux',
  'economy',
  'article',
  'Le Canada perd 4 700 emplois, le chômage atteint 6,7 % et complique les perspectives de taux',
  'L’embauche a stagné en octobre, même si les prix de l’énergie avaient poussé la Banque du Canada à resserrer sa politique.',
  '<ul>
<li><strong>Statistique Canada a indiqué que l’emploi a peu varié en octobre,</strong><span> en baisse de 4&nbsp;700.</span></li>
<li><strong>Le taux de chômage a augmenté de 0,2&nbsp;point de pourcentage pour s’établir à 6,7&nbsp;%,</strong><span> alors que 33&nbsp;000 personnes de plus cherchaient du travail.</span></li>
<li><strong>Le chômage chez les jeunes est passé à 13,7&nbsp;%,</strong><span> une détérioration plus marquée que la moyenne nationale.</span></li>
<li><strong>La construction a gagné 16</strong><span>&nbsp;000 emplois et l’éducation 15&nbsp;000, masquant des résultats plus faibles dans le commerce de détail et dans les régions.</span></li>
<li><strong>La situation du marché du travail complique les décisions de politique monétaire lorsque l’inflation tirée par le pétrole et la demande intérieure évoluent en sens contraire.</strong></li>
</ul>',
  '<p>Statistique Canada a indiqué que l’emploi a peu varié en octobre, en baisse de 4&nbsp;700. Le taux de chômage a augmenté de 0,2&nbsp;point de pourcentage pour s’établir à 6,7&nbsp;%, alors que 33&nbsp;000 personnes de plus cherchaient du travail. La distinction importante, pour un conseiller, est celle qui sépare l’observation rapportée de l’inférence que les investisseurs sont tentés d’en tirer.</p><h2>Un taux de chômage plus élevé n’équivaut pas à des mises à pied massives</h2><p>Le chômage chez les jeunes est passé à 13,7&nbsp;%, une détérioration plus marquée que la moyenne nationale. Le taux de chômage a augmenté de 0,2&nbsp;point de pourcentage pour s’établir à 6,7&nbsp;%, alors que 33&nbsp;000 personnes de plus cherchaient du travail. Cela importe, car une même manchette peut avoir des conséquences différentes pour un investisseur à long terme, un ménage qui finance des dépenses à court terme et un client détenant une position concentrée. La bonne réponse dépend des besoins de flux de trésorerie, de la valorisation et de la capacité à prendre des risques, et non simplement du sens de la dernière donnée publiée.</p><p>Pour les conseillers canadiens, la question pratique est de savoir quelle hypothèse du plan du client a réellement changé. Un changement temporaire de sentiment peut modifier les cours sans modifier les obligations futures. À l’inverse, une proposition réglementaire, une détérioration de l’emploi ou une perturbation persistante de l’approvisionnement peut modifier les flux de trésorerie attendus sur lesquels repose le plan. Cette distinction est au cœur d’un examen rigoureux.</p><h2>La répartition sectorielle importe pour la planification des ménages</h2><p>La construction a gagné 16&nbsp;000 emplois et l’éducation 15&nbsp;000, masquant des résultats plus faibles dans le commerce de détail et dans les régions. Le chômage chez les jeunes est passé à 13,7&nbsp;%, une détérioration plus marquée que la moyenne nationale. Cela importe, car une même manchette peut avoir des conséquences différentes pour un investisseur à long terme, un ménage qui finance des dépenses à court terme et un client détenant une position concentrée. La bonne réponse dépend des besoins de flux de trésorerie, de la valorisation et de la capacité à prendre des risques, et non simplement du sens de la dernière donnée publiée.</p><p>Pour les conseillers canadiens, la question pratique est de savoir quelle hypothèse du plan du client a réellement changé. Un changement temporaire de sentiment peut modifier les cours sans modifier les obligations futures. À l’inverse, une proposition réglementaire, une détérioration de l’emploi ou une perturbation persistante de l’approvisionnement peut modifier les flux de trésorerie attendus sur lesquels repose le plan. Cette distinction est au cœur d’un examen rigoureux.</p><div class="hdq-chart"><div style="background:#fff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;"><div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;font-size:13px;font-weight:700;">ÉCONOMIE | COMPARAISON VÉRIFIÉE</div><div style="padding:12px 14px 8px;"><script>(function(){var _cs=document.currentScript;var NS="http://www.w3.org/2000/svg";function el(t,a,v){var e=document.createElementNS(NS,t);Object.keys(a).forEach(function(k){e.setAttribute(k,a[k]);});if(v!==undefined)e.textContent=v;return e;}var svg=el("svg",{viewBox:"0 0 680 300",width:"100%",role:"img","aria-label":"économie, comparaison vérifiée"});var labels=["Variation d’emploi (milliers)", "Chômeurs en plus (milliers)", "Gain en construction (milliers)", "Gain en éducation (milliers)"],values=[-4.7, 33, 16, 15],max=33;svg.appendChild(el("line",{x1:205,y1:15,x2:205,y2:265,stroke:"#dddddd"}));values.forEach(function(v,i){var y=28+i*(225/values.length);var w=Math.abs(v)/max*375;svg.appendChild(el("text",{x:8,y:y+15,"font-size":12,fill:"#444444"},labels[i]));svg.appendChild(el("rect",{x:205,y:y,width:w,height:25,fill:v<0?"#b65a52":"#526a80",rx:2}));svg.appendChild(el("text",{x:210+w,y:y+17,"font-size":12,fill:"#222222"},v.toLocaleString("fr-CA")));});_cs.parentNode.appendChild(svg);})();</script></div><div style="font-size:10px;color:#888;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Statistique Canada, Enquête sur la population active d’octobre 2026, publiée le 6 novembre 2026. Les valeurs reflètent les unités de la source telles qu’indiquées. | hdq.ca</div></div></div><p style="font-size:11px;color:#666;">Note sur le graphique&nbsp;: les comparaisons reposent sur les observations publiées et les unités indiquées&nbsp;; les unités mixtes ne doivent pas être interprétées comme des variations en pourcentage équivalentes.</p><h2>Pourquoi la prochaine décision sur les taux comporte un risque dans les deux sens</h2><p>La situation du marché du travail complique les décisions de politique monétaire lorsque l’inflation tirée par le pétrole et la demande intérieure évoluent en sens contraire. La construction a gagné 16&nbsp;000 emplois et l’éducation 15&nbsp;000, masquant des résultats plus faibles dans le commerce de détail et dans les régions. Cela importe, car une même manchette peut avoir des conséquences différentes pour un investisseur à long terme, un ménage qui finance des dépenses à court terme et un client détenant une position concentrée. La bonne réponse dépend des besoins de flux de trésorerie, de la valorisation et de la capacité à prendre des risques, et non simplement du sens de la dernière donnée publiée.</p><p>Pour les conseillers canadiens, la question pratique est de savoir quelle hypothèse du plan du client a réellement changé. Un changement temporaire de sentiment peut modifier les cours sans modifier les obligations futures. À l’inverse, une proposition réglementaire, une détérioration de l’emploi ou une perturbation persistante de l’approvisionnement peut modifier les flux de trésorerie attendus sur lesquels repose le plan. Cette distinction est au cœur d’un examen rigoureux.</p><p>La situation du marché du travail complique les décisions de politique monétaire lorsque l’inflation tirée par le pétrole et la demande intérieure évoluent en sens contraire. Une règle de décision documentée, une analyse de scénarios et un suivi planifié peuvent être plus utiles qu’une prédiction assurée. Les chiffres et l’état des politiques sont présentés à la date limite de recherche de 6&nbsp;h&nbsp;48, heure de Toronto, le 10 novembre 2026.</p>',
  '<div class="toolkit-section"><div class="toolkit-section-label">Ce qu’ils ressentent</div><p>Les clients peuvent être partagés entre le soulagement devant le dernier mouvement et la crainte que l’incertitude sous-jacente n’ait pas disparu. Ceux qui ont récemment modifié leur répartition de l’actif peuvent être particulièrement sensibles à la prochaine manchette.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Quoi dire</div><p>Les derniers chiffres méritent de l’attention, mais ils n’exigent pas, à eux seuls, un changement de portefeuille. Nous pouvons examiner ce qui a changé, ce qui reste incertain et si votre plan actuel est toujours adapté.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Qui est touché</div><p>Les clients qui détiennent des positions concentrées, qui prévoient des retraits, qui ont des besoins de refinancement ou dont l’horizon de placement est court méritent une discussion plus précise.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Liste de vérification</div><ul><li>Examiner la concentration et les besoins de liquidité.</li><li>Comparer les expositions actuelles avec la politique de placement écrite.</li><li>Vérifier les dates et l’état d’avancement législatif avant de mettre en œuvre des changements fiscaux.</li><li>Consigner la justification de tout ajustement recommandé.</li></ul></div><div class="toolkit-section"><div class="toolkit-section-label">Modèle de courriel de suivi</div><div class="email-template" id="respond-email"><strong>Objet&nbsp;: Un éclairage utile sur l’actualité économique</strong><br><br>Bonjour [Nom du client],<br><br>Je souhaite vous faire part d’un bref point sur l’économie. Statistique Canada a indiqué que l’emploi a peu varié en octobre, en baisse de 4&nbsp;700. C’est un bon moment pour revoir vos objectifs et votre positionnement actuel plutôt que de réagir à une seule séance. Faites-moi savoir si vous souhaitez planifier un bref examen.<br><br>Cordialement,<br>[Votre nom]<br><br><em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em></div><button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button></div>',
  '<div class="toolkit-section"><div class="toolkit-section-label">Profils de clients à cibler</div><p><strong>Clients ayant des expositions concentrées&nbsp;:</strong> ménages dont les décisions sont les plus sensibles aux derniers développements économiques.</p><p><strong>Investisseurs sur le point de prendre une décision financière&nbsp;:</strong> personnes qui évaluent un changement de portefeuille, un choix de financement ou un événement de liquidité.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Phrase d’accroche</div><p>Les dernières manchettes offrent l’occasion de distinguer la réaction immédiate du marché de ce qui a réellement changé dans les faits sous-jacents.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Proposition de valeur</div><p>Proposer un examen concis, fondé sur des faits, des expositions du client, de ses échéances de décision et de ses scénarios de baisse, sans promettre de résultat sur les marchés.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Questions de découverte</div><ul><li>Qu’est-ce qui vous a amené à reconsidérer votre stratégie actuelle&nbsp;?</li><li>Quel engagement financier à venir est le plus important&nbsp;?</li><li>Quel niveau de volatilité vous obligerait à modifier votre plan&nbsp;?</li></ul></div><div class="toolkit-section"><div class="toolkit-section-label">Modèle de courriel de prospection</div><div class="email-template" id="prospect-email"><strong>Objet&nbsp;: Un éclairage utile sur l’actualité économique</strong><br><br>Bonjour [Nom du client],<br><br>J’ai remarqué les derniers développements économiques. Statistique Canada a indiqué que l’emploi a peu varié en octobre, en baisse de 4&nbsp;700. Plutôt que de prendre une décision à partir d’une seule manchette, je serais heureux de vous présenter un court cadre d’analyse pour évaluer ce qui compte pour vos objectifs. Une conversation de 15&nbsp;minutes vous serait-elle utile&nbsp;?<br><br>Cordialement,<br>[Votre nom]<br><br><em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em></div><button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button></div>',
  '[{"value": "−4 700", "label": "Variation de l’emploi en octobre"}, {"value": "6,7 %", "label": "Taux de chômage"}, {"value": "13,7 %", "label": "Chômage chez les jeunes"}, {"value": "2,2 %", "label": "Croissance annuelle des salaires"}]',
  'economy-156.jpg',
  'Image éditoriale provisoire de HDQ.',
  6,
  '2026-11-10T06:58:00',
  'entity:economy,theme:november-2026,theme:advisor-planning',
  1,
  'Statistique Canada, Enquête sur la population active d’octobre 2026, publiée le 6 novembre 2026 ; Banque du Canada, décision de politique monétaire du 28 octobre 2026. Source principale : https://www150.statcan.gc.ca/n1/daily-quotidien/261106/dq261106a-eng.htm',
